-- 2026-11-13 — Judging talks for the Nov 14 tournament, editable in the app.
-- Asked by: [who? typed in Claude Code]: "make it to where we can make manual changes to the innovation and robot game paragraphs through the app."
-- Same text as updates/PRESENTATION.md (2026-11-13) and presentation/2026-11-14-judging-script.html.
-- One row per part, in the judges' rubric order. say = JSON list of lines; [[...]] = a blank the team fills in.
CREATE TABLE IF NOT EXISTS talk_parts (
  id INTEGER PRIMARY KEY,
  talk TEXT NOT NULL,            -- 'ip' = Innovation Project, 'rd' = Robot Design (the robot game talk)
  sort_order INTEGER NOT NULL,
  phase TEXT, row_name TEXT, goal TEXT,
  core_values INTEGER DEFAULT 0, -- 1 = row also counts for Core Values
  speaker TEXT NOT NULL,
  say TEXT NOT NULL,             -- JSON list of lines
  show_what TEXT, photos TEXT,   -- photos = JSON list of files in app/images/
  check_note TEXT,
  source TEXT DEFAULT 'update',
  edited_at TEXT                 -- set when someone edits the part in the app
);
