INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (1, 'ip', 1, 'OPENING', 'Say hi + the hook', NULL, 0, 'Isla', '["Hi! We are the Rooted Warriors from Flagstaff, Arizona.","(Everyone says their own name, down the line.)","Imagine driving on I-17 at night when an elk steps onto the road. Flagstaff is surrounded by forest, and elk and other animals cross our highways all the time.","Wildlife bridges help, but only if they are in the right places. So we built a smart wildlife camera with AI that shows where animals really cross."]', 'Whole team standing together, trifold behind you', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (2, 'ip', 2, 'IDENTIFY', 'Problem definition', 'Clear definition of the problem', 0, 'Adeline', '["Here is our problem. Nate Reagan from Arizona Game and Fish told us I-17 has about 300 animal strikes a year.","A new 24-million-dollar wildlife bridge should cut those crashes by 90 percent. But how will anyone know if animals really use it?"]', 'Problem section of the trifold', '[]', 'The notebook never wrote down a one-sentence problem statement. This is a draft from your Nate notes: change it into your own words.', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (3, 'ip', 3, 'IDENTIFY', 'Research', 'Clear, detailed research from a variety of sources', 1, 'Fynn', '["We used more than one source.","We interviewed an expert, Nate Reagan, with five questions we wrote. He said Game and Fish uses GPS collars, live-stream cameras and thermal goggles, but not much AI.","We also used Google Gemini to compare computers, and learned a Raspberry Pi uses too much battery and cannot sleep."]', 'Expert notes / question list', '[]', 'Only 2 research sources are logged (Gemini Oct 3, Nate Oct 5). "A variety of sources" scores higher: add any website, article, book or video you used.', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (4, 'ip', 4, 'DESIGN', 'Project plan', 'Clear evidence of an effective project plan', 0, 'Thea', '["We made a project plan as a Gantt chart in our team app.","Every task has an owner and dates, from picking the design to practicing this talk.","We started October 2."]', 'Gantt chart (app, Innovation Project page, printed or on the trifold)', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (5, 'ip', 5, 'DESIGN', 'Team involvement', 'Clear evidence that development involved all team members', 1, 'Isla', '["Everybody had a job.","Thea led the design and programmed the camera. Nolan wired it with Thea''s help, and Nolan and Weston soldered it.","Adeline and Thea kept our expert notes and made the trifold. I [[what Isla did]], and Fynn [[what Fynn did]]."]', 'Soldering photos', '["11-1-soldering-2.jpg"]', 'Isla now gives this part (switched with Weston, Nov 13). The notebook has no Innovation Project job logged for Isla or Fynn. Judges score "all team members" here, so fill the yellow part with something true (testing the camera, research, the trifold, practicing the talk…).', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (6, 'ip', 6, 'CREATE', 'Innovation', 'Detailed explanation of innovation in the solution', 1, 'Thea', '["What is new? Our camera is tiny, cheap and smart.","It only saves a picture when the picture changes or the motion sensor fires, then sends it over its own Wi-Fi to our Raspberry Pi.","The Pi''s AI, SpeciesNet, names the animal with no internet, and blurs out any people."]', 'Pi Camera Station touchscreen', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (7, 'ip', 7, 'CREATE', 'Model / drawing', 'Detailed model/drawing that represents the solution', 0, 'Nolan', '["This is our real camera.","Inside: a Seeed XIAO ESP32-S3 Sense board, a motion sensor, a clock and a mode switch.","Our wiring diagram shows every wire. It runs on USB-C, from a phone charger or our solar box."]', 'The real camera + wiring diagram (app, Innovation Project Details)', '["11-1-soldering-1.jpg"]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (8, 'ip', 8, 'ITERATE', 'Sharing', 'Solution shared with multiple people/groups', 0, 'Adeline', '["On October 5 we shared our idea with Nate Reagan from Arizona Game and Fish.","He told us not to live stream, and that cameras spread out over a wide area work best.","We also showed it to [[who else? family, teachers, a class, another team]]."]', 'Communication table (app, Innovation Project page)', '[]', 'Only ONE sharing is logged (Nate). "Accomplished" needs MULTIPLE people or groups. Before Saturday: show it to family, a teacher or a class, and say what they said.', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (9, 'ip', 9, 'ITERATE', 'Improvements', 'Clear evidence of improvements based on feedback', 0, 'Weston', '["Feedback changed our design.","Our first plan put a Raspberry Pi in the forest. After Fynn''s research, we switched to the tiny camera.","Because of Nate, we don''t live stream: the Pi blurs people, and we check every photo before sharing."]', 'Before → after on the trifold (Pi in the forest → tiny camera)', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (10, 'ip', 10, 'COMMUNICATE', 'Explanation & impact', 'Clear explanation of solution and its impact on others', 1, 'Weston', '["Here is how it all works together: animal, camera, Pi, AI, and then we choose what to share.","We can''t get Game and Fish''s data, so we collect our own.","Knowing where animals cross helps put crossings in the right places: fewer crashes for animals and drivers."]', 'Point along the path on the trifold: camera → Pi → AI → us', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (11, 'ip', 11, 'COMMUNICATE', 'Pride & enthusiasm', 'Presentation clearly shows pride or enthusiasm', 1, 'Nolan', '["We are so proud!","We built two cameras and did real soldering. On November 9 the whole system worked for the first time: camera, to Pi, to AI!","It only found people waving, because we tested indoors. Next, it goes outside to find real animals."]', 'Big smiles. Hold up the camera.', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (12, 'ip', 12, 'CLOSING', 'Next steps + thank you', NULL, 0, 'Fynn', '["Next, we''ll fix our second camera, put one outside facing the forest, and ask ADOT about a wildlife bridge.","Thank you! Do you have any questions for us?","(Everyone:) We are the Rooted Warriors!"]', 'Everyone together', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (13, 'rd', 1, 'OPENING', 'Meet our robot', NULL, 0, 'Weston', '["This is our robot!","It''s low and wide with extra bracing, so it doesn''t tip and it turns accurately.","We built three copies of the base, so we can test three attachments at once and have a spare."]', 'The robot (hold it up)', '[]', 'The notebook never wrote down WHY three copies. Is "test three at once + a spare" really your reason? Say your real one.', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (14, 'rd', 2, 'IDENTIFY', 'Mission strategy', 'Clear evidence of mission strategy', 0, 'Isla', '["Our strategy: try every mission. We have an attachment for all 15.","A match is only 150 seconds, so we group nearby missions into nine runs.","Fynn and I timed them with a stopwatch: Missions 6, 7 and 11 together take only 17 seconds."]', 'Fynn + Isla''s timing notes, run plan in the app', '["11-8-mission-timing-notes.webp"]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (15, 'rd', 3, 'IDENTIFY', 'Use of resources', 'Clear use of building or coding resources to support the strategy', 1, 'Adeline', '["We code in Pybricks, using Python.","I made a program template that every mission starts from, so they all set up the motors and wheels the same way.","We also used the official rulebook, Coach CJ, and our team app."]', 'Laptop: Pybricks with the template', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (16, 'rd', 4, 'DESIGN', 'All members contributed', 'Clear evidence that all team members contributed ideas', 1, 'Thea', '["Everyone contributed ideas.","On September 19, all six of us built or programmed something. Nolan had the idea to put Missions 2 and 3 on one attachment.","And we build on each other''s work: Fynn started the Forest Elder attachment, Isla finished it, and Adeline rebuilt it."]', '"Who''s been doing what" in the app', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (17, 'rd', 5, 'DESIGN', 'Skills in all members', 'Clear evidence of building and coding skills in all team members', 0, 'Weston', '["Every one of us builds AND codes.","I built the base, then my first attachment for Mission 14, then programmed Mission 9.","Thea was a builder and wrote her first program for Mission 12. Nolan builds attachments and programmed Missions 2 and 3."]', 'Mission 14 attachment', '["11-2-mission-14.jpg"]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (18, 'rd', 6, 'CREATE', 'Attachments', 'Clear explanation of innovative attachments and their purpose', 0, 'Nolan', '["Our attachments do more than one mission per trip.","Our 2-and-3 attachment knocks the seeds loose and flips the rock. One attachment does Missions 8 and 9 at the big tree, and I built one for 6, 7 and 11.","Our mascot even rides along for Mission 13!"]', 'The 2+3 attachment, the 8+9 attachment, the mascot', '["11-2-mission-2-3.jpg","11-2-mission-8-9.jpg"]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (19, 'rd', 7, 'CREATE', 'Code / sensors', 'Clear explanation of innovative code and/or sensor use', 0, 'Fynn', '["Our base has no room for color sensors.","So our code uses the gyro in the hub to drive straight and turn exactly, and measures distance with wheel rotations.","It knows our wheels are 49.5 millimeters wide and 160 millimeters apart. Ports B and F run the attachments."]', 'Laptop: a mission program', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (20, 'rd', 8, 'ITERATE', 'Testing', 'Clear evidence of repeated testing of robot and code', 0, 'Isla', '["We test over and over.","Mission 14 worked 5 out of 5 times, and so did Missions 2 and 3. Missions 4 and 5 worked 4 out of 5.","On November 8, Fynn and I tested every mission and listed what needs work, like Mission 15''s yellow arm."]', 'Test results in the app (Robot Design page)', '[]', 'Did you count any more tries since Nov 8? Add them: more "5 out of 5" numbers make this row stronger.', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (21, 'rd', 9, 'ITERATE', 'Improvements', 'Clear evidence of improvements based on testing', 1, 'Adeline', '["Our code changed 18 times this season.","The Mission 4 program changed at four practices in a row, grew from 19 lines to 57, and got faster.","We rebuilt the Forest Elder attachment because [[why?]], and split Mission 12 into two parts to fit our runs."]', 'Code history grid in the app (Coding page)', '[]', 'The notebook never says WHY the Forest Elder (Mission 12) was rebuilt on Oct 12. Judges love "we saw ___, changed ___, now ___."', 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (22, 'rd', 10, 'COMMUNICATE', 'Process & lessons learned', 'Detailed explanation of process and lessons learned', 1, 'Thea', '["Our process: build, code, test, fix, repeat.","Lesson one: time real runs. Our first plan was all guesses and way over 150 seconds.","Lesson two: combine missions to save trips. Lesson three: write everything down, so we know who did what and every change."]', 'Engineering notebook / app', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (23, 'rd', 11, 'COMMUNICATE', 'Pride & enthusiasm', 'Team clearly shows pride or enthusiasm', 1, 'Nolan', '["We are proud of how far we came!","In August we had one robot base. Now every mission has an attachment, and one run takes only 7 seconds.","My favorite moment was [[your favorite moment]]."]', 'Big smiles!', '[]', NULL, 'update');
INSERT INTO talk_parts (id, talk, sort_order, phase, row_name, goal, core_values, speaker, say, show_what, photos, check_note, source) VALUES (24, 'rd', 12, 'CLOSING', 'Next steps + thank you', NULL, 0, 'Fynn', '["Next, we''ll fix Mission 15''s yellow arm, finish timing our last runs, and keep counting our tries.","Thank you! Do you have any questions for us?","(Everyone:) We are the Rooted Warriors!"]', 'Everyone together', '[]', NULL, 'update');
